WITH ranked AS ( SELECT id, parent_id, content, create_time, reply_user_id, user_id, article_id, status, like_count, ROW_NUMBER() OVER (PARTITION BY parent_id ORDER BY like_count DESC) AS rn FROM TB_WZY_BLOG_COMMENT WHERE level_one_id IN
#{id}
AND deleted = 0 ) SELECT t0.article_id as articleId, t0.id as id, t0.content as content, t0.create_time as createTime, t0.reply_user_id as replyUserId, t0.user_id as userId, t0.parent_id as parentId, t0.status as status, t0.like_count as likeCount FROM ranked t0 WHERE t0.rn <= #{limit} ORDER BY t0.parent_id, t0.create_time

mapper.update:
UPDATE TB_WZY_BLOG_COMMENT
SET like_count = GREATEST(
    like_count + CASE id

        WHEN #{it.commentId} THEN #{it.delta}

    END,
    0
)
WHERE id IN

    #{it.commentId}
